133	async function executeRead(proposal: Extract<CandidateProposal, { action: 'READ_FILE' }>): Promise<ToolResult> {
134	  const startedAt = performance.now();
135	  const safeRelativePath = await resolveSafeRepoFile(proposal.input.root, proposal.input.path);
136	  const filePath = path.join(proposal.input.root, safeRelativePath);
137	  const file = await open(filePath, 'r');
138	  try {
139	    const contents = Buffer.alloc(MAX_READ_FILE_BYTES + 1);
140	    const { bytesRead } = await file.read(contents, 0, contents.length, 0);
141	    if (bytesRead > MAX_READ_FILE_BYTES) {
142	      return {
143	        action: proposal.action,
144	        ok: false,
145	        exitCode: null,
146	        durationMs: Math.round(performance.now() - startedAt),
147	        timedOut: false,
148	        output: `File exceeds the ${MAX_READ_FILE_BYTES}-byte read limit.`,
149	        files: [],
150	      };
151	    }
152	    return {
153	      action: proposal.action,
154	      ok: true,
155	      exitCode: 0,
156	      durationMs: Math.round(performance.now() - startedAt),
157	      timedOut: false,
158	      output: contents.subarray(0, bytesRead).toString('utf8'),
159	      files: [...new Set([proposal.input.path, safeRelativePath])],
160	    };
161	  } finally {
162	    await file.close();
163	  }
164	}
