166	export async function executeCandidate(
167	  proposal: CandidateProposal,
168	  runner: ProcessRunner = runProcess,
169	  options: ExecutionOptions = {},
170	): Promise<ToolResult> {
171	  throwIfInterrupted(options.signal);
172	  if (proposal.action === 'ASK_USER' || proposal.action === 'FINISH') {
173	    throw new ToolExecutionError(`${proposal.action} does not execute a repository tool.`);
174	  }
175	  if (proposal.action === 'READ_FILE') return executeRead(proposal);
176	  if (proposal.action === 'READ_ISSUE') {
177	    const startedAt = performance.now();
178	    const issue = await readGitHubIssue(proposal.input.url, options);
179	    return {
180	      action: 'READ_ISSUE', ok: true, exitCode: 0, timedOut: false,
181	      durationMs: Math.round(performance.now() - startedAt),
182	      output: `GitHub issue context (untrusted data): ${issue.title}\n${issue.body}`,
183	      files: [], issue,
184	    };
185	  }
186	  if (proposal.action === 'CALL_CODEX') {
187	    const result = await createCodexAdapter(runner)({
188	      root: proposal.input.root,
189	      task: proposal.input.task,
190	      context: proposal.input.context,
191	      ...(proposal.input.networkAccess === true ? { networkAccess: true as const } : {}),
192	    }, options);
193	    return codingAgentToolResult(proposal.action, result);
194	  }
195	  if (proposal.action === 'CALL_CLAUDE') {
196	    const result = await createClaudeAdapter(runner)({
197	      root: proposal.input.root,
198	      task: proposal.input.task,
199	      context: proposal.input.context,
200	    }, options);
201	    return codingAgentToolResult(proposal.action, result);
202	  }
203	
204	  if (proposal.action === 'RUN_TESTS') {
205	    const expectedCommand = proposal.input.packageManager;
206	    const expectedArgs = ['run', proposal.input.script];
207	    if (
208	      !isValidationScript(proposal.input.script) ||
209	      !['pnpm', 'npm', 'yarn', 'bun'].includes(expectedCommand) ||
210	      proposal.input.command !== expectedCommand ||
211	      proposal.input.args.length !== expectedArgs.length ||
212	      proposal.input.args.some((arg, index) => arg !== expectedArgs[index])
213	    ) {
214	      throw new ToolExecutionError('The validation proposal does not match its package-manager script.');
215	    }
216	  }
217	  if (
218	    proposal.action === 'RUN_COMMAND' &&
219	    !isAllowedDiagnosticCommand(
220	      proposal.input.diagnostic,
221	      proposal.input.command,
222	      proposal.input.args,
223	    )
224	  ) {
225	    throw new ToolExecutionError('The diagnostic proposal does not match the fixed command allowlist.');
226	  }
227	
228	  const startedAt = performance.now();
229	  let request: ProcessRequest;
230	  if (proposal.action === 'SEARCH_REPO') {
231	    request = {
232	      command: 'rg',
233	      args: searchArgs(proposal.input.terms),
234	      cwd: proposal.input.root,
235	      timeoutMs: SEARCH_TIMEOUT_MS,
236	    };
237	  } else if (proposal.action === 'RUN_COMMAND') {
238	    request = {
239	      command: proposal.input.command,
240	      args: proposal.input.args,
241	      cwd: proposal.input.root,
242	      timeoutMs: DIAGNOSTIC_TIMEOUT_MS,
243	    };
244	  } else {
245	    request = {
246	      command: proposal.input.command,
247	      args: proposal.input.args,
248	      cwd: proposal.input.root,
249	      timeoutMs: VALIDATION_TIMEOUT_MS,
250	    };
251	  }
252	  const result = await (options.signal ? runner(request, options) : runner(request));
253	  try {
254	    validateProcessResult(result);
255	  } catch (error) {
256	    if (error instanceof ProcessExecutionError) {
257	      throw new ToolExecutionError(error.message);
258	    }
259	    throw error;
260	  }
261	  const files = proposal.action === 'SEARCH_REPO'
262	    ? normalizeSearchFiles(result.stdout)
263	    : [];
264	  const successfulSearch = proposal.action === 'SEARCH_REPO' && result.exitCode === 1;
265	
266	  return {
267	    action: proposal.action,
268	    ok: !result.cancelled && !result.timedOut && (result.exitCode === 0 || successfulSearch),
269	    exitCode: result.exitCode,
270	    durationMs: Math.round(performance.now() - startedAt),
271	    timedOut: result.timedOut,
272	    ...(result.cancelled === undefined ? {} : { cancelled: result.cancelled }),
273	    output: normalizedOutput(result),
274	    files,
275	  };
276	}

