 42	export function validationWorkflow(
 43	  scripts: string[],
 44	  commands: Record<string, string>,
 45	  manager: RepoSnapshot['packageManager'],
 46	): Pick<RepoSnapshot, 'requiredValidationScripts' | 'validationScriptCoverage'> {
 47	  const exact = VALIDATION_NAMES.filter((name) => scripts.includes(name));
 48	  const requiredValidationScripts = exact.length > 0 ? [...exact] : [...scripts];
 49	  const validationScriptCoverage: Record<string, string[]> = {};
 50	  function covered(script: string, seen: Set<string>, depth = 0): void {
 51	    if (seen.has(script) || depth >= 8 || seen.size >= 100) return;
 52	    seen.add(script);
 53	    for (const dependency of scriptDependencies(commands[script] ?? '', manager)) {
 54	      if (scripts.includes(dependency)) covered(dependency, seen, depth + 1);
 55	    }
 56	  }
 57	  for (const script of scripts) {
 58	    const seen = new Set<string>();
 59	    covered(script, seen);
 60	    validationScriptCoverage[script] = [...seen];
 61	  }
 62	  return { requiredValidationScripts, validationScriptCoverage };
 63	}
 64	
 65	export function requiredValidationScripts(state: AgentState): string[] {
 66	  return [...new Set([
 67	    ...(state.repo.requiredValidationScripts ?? state.repo.validationScripts),
 68	    ...(state.evidence?.issue?.requestedValidationScripts ?? []),
 69	    ...clarificationValidation(state).scripts,
 70	  ])];
 71	}
 72	
 73	function validationOutcomes(state: AgentState): Map<string, boolean> {
 74	  const generation = state.evidence?.validationGeneration ?? 0;
 75	  const records = state.evidence?.validations ??
 76	    (state.evidence?.validation ? [state.evidence.validation] : undefined);
 77	  const outcomes = new Map<string, boolean>();
 78	  for (const result of (records ?? []).filter((item) => item.generation === generation)
 79	    .sort((left, right) => left.iteration - right.iteration)) {
 80	    const passed = result.passed && result.exitCode === 0 && !result.timedOut;
 81	    const covered = passed ? state.repo.validationScriptCoverage?.[result.script] ?? [result.script] : [result.script];
 82	    for (const script of covered) outcomes.set(script, passed);
 83	  }
 84	  return outcomes;
 85	}
 86	
 87	export function pendingValidationScripts(state: AgentState): string[] {
 88	  const required = requiredValidationScripts(state);
 89	  // Retain compatibility for older decision-only single-check snapshots.
 90	  if (state.evidence?.validations === undefined && state.evidence?.validation === undefined &&
 91	    (state.evidence?.validationGeneration ?? 0) === 0 && required.length === 1 &&
 92	    state.tests.ran && state.tests.passed === true) return [];
 93	  const outcomes = validationOutcomes(state);
 94	  return required.filter((script) => outcomes.get(script) !== true);
 95	}
 96	
 97	export type ValidationCheck = { script: string; status: 'passed' | 'failed' | 'pending' };
 98	
 99	export function validationChecks(state: AgentState): ValidationCheck[] {
100	  const outcomes = validationOutcomes(state);
101	  const pending = new Set(pendingValidationScripts(state));
102	  return requiredValidationScripts(state).map((script) => ({
103	    script,
104	    status: !pending.has(script) ? 'passed' : outcomes.get(script) === false ? 'failed' : 'pending',
105	  }));
106	}
107	
108	export function hasFailedValidation(state: AgentState): boolean {
109	  const outcomes = validationOutcomes(state);
110	  return requiredValidationScripts(state).some((script) => outcomes.get(script) === false) ||
111	    (outcomes.size === 0 && state.tests.ran && state.tests.passed === false);
112	}
113	
114	export function hasPassedValidation(state: AgentState): boolean {
115	  return !state.evidence?.repoRefreshRequired && !hasOmittedValidationRequirements(state) &&
116	    state.tests.ran && state.tests.passed === true &&
117	    requiredValidationScripts(state).length > 0 && pendingValidationScripts(state).length === 0;
118	}
119	
120	export function selectPendingValidation(state: AgentState): string | undefined {
121	  const pending = pendingValidationScripts(state);
122	  if (pending.length === 0) return undefined;
123	  const candidates = state.repo.validationScripts.filter(isValidationScript);
124	  const score = (script: string): number =>
125	    (state.repo.validationScriptCoverage?.[script] ?? [script]).filter((name) => pending.includes(name)).length;
126	  const priority = (script: string): number => {
127	    const index = VALIDATION_NAMES.findIndex((name) => script === name || script.startsWith(`${name}:`));
128	    return index < 0 ? VALIDATION_NAMES.length : index;
129	  };
130	  return candidates.filter((script) => score(script) > 0)
131	    .sort((left, right) => score(right) - score(left) || priority(left) - priority(right) || left.localeCompare(right))[0];
132	}

