221	  const searchedSet = new Set(searched);
222	  const knownPaths = state.repo.topLevelFiles
223	    .filter((entry) => !entry.endsWith('/'))
224	    .filter((candidate) => !searchedSet.has(candidate))
225	    .filter((candidate) => !state.filesRead.includes(candidate));
226	  const preferences = [...REPOSITORY_INSTRUCTION_FILES, 'README.md', 'package.json', 'PLAN.md'];
227	  const taskPaths = new Set((state.task.match(SEARCH_TOKEN) ?? [])
228	    .map((token) => token.replace(/^\.\//u, '').replace(/[.:]+$/u, '')));
