   156	function isBelowRoot(root: string, candidate: string): boolean {
   157	  const relative = path.relative(root, candidate);
   158	  return relative !== '' && !relative.startsWith(`..${path.sep}`) && relative !== '..' && !path.isAbsolute(relative);
