   167	export function deriveSearchTerms(task: string): string[] {
   168	  const tokens = task.match(SEARCH_TOKEN) ?? [];
   169	  const terms: string[] = [];
   170	
   171	  for (const token of tokens) {
   172	    const normalized = token.slice(0, MAX_SEARCH_TERM_LENGTH);
   173	    if (normalized.length < 2 || STOP_WORDS.has(normalized.toLowerCase())) continue;
   174	    if (terms.some((term) => term.toLowerCase() === normalized.toLowerCase())) continue;
   175	    terms.push(normalized);
   176	    if (terms.length >= MAX_SEARCH_TERMS) break;
   177	  }
