   182	export async function resolveSafeRepoFile(root: string, candidatePath: string): Promise<string> {
   183	  if (!candidatePath || path.isAbsolute(candidatePath) || candidatePath.includes('\0')) {
   184	    throw new CandidateSelectionError('The file candidate must be a relative repository path.');
   185	  }
   186	
   187	  const resolvedRoot = await realpath(root);
   188	  const lexicalCandidate = path.resolve(resolvedRoot, candidatePath);
   189	  if (!isBelowRoot(resolvedRoot, lexicalCandidate)) {
   190	    throw new CandidateSelectionError('The file candidate escapes the repository root.');
   191	  }
   192	
   193	  const relativeCandidate = path.relative(resolvedRoot, lexicalCandidate);
   194	  if (isSensitivePath(relativeCandidate)) {
   195	    throw new CandidateSelectionError('The file candidate is blocked by the secret-file policy.');
   196	  }
   197	
   198	  let resolvedCandidate: string;
   199	  try {
   200	    resolvedCandidate = await realpath(lexicalCandidate);
   201	  } catch {
   202	    throw new CandidateSelectionError('The file candidate does not exist.');
   203	  }
   204	  if (!isBelowRoot(resolvedRoot, resolvedCandidate)) {
   205	    throw new CandidateSelectionError('The file candidate resolves outside the repository root.');
   206	  }
   207	  if (isSensitivePath(path.relative(resolvedRoot, resolvedCandidate))) {
   208	    throw new CandidateSelectionError('The resolved file candidate is blocked by the secret-file policy.');
   209	  }
   210	
   211	  const fileStat = await lstat(resolvedCandidate);
   212	  if (!fileStat.isFile()) {
   213	    throw new CandidateSelectionError('The file candidate is not a regular file.');
   214	  }
   215	
   216	  return path.relative(resolvedRoot, resolvedCandidate);
   217	}
