    27	// Only a conjunction of plain package-script calls proves coverage. Flags,
    28	// shell substitutions, ORs, and opaque tool commands prove nothing further.
    29	function scriptDependencies(command: string, manager: RepoSnapshot['packageManager']): string[] {
    30	  const dependencies: string[] = [];
    31	  for (const part of command.split('&&')) {
    32	    const match = /^(pnpm|npm|yarn|bun)\s+(?:(run)\s+)?([a-zA-Z0-9][a-zA-Z0-9:_-]{0,199})$/u.exec(part.trim());
    33	    if (!match || match[1] !== manager || !match[3]) return [];
    34	    // Other bare commands may name package-manager builtins (e.g. bun test
    35	    // or yarn check), which do not prove execution of the declared script.
    36	    if (!match[2] && !(manager === 'npm' && match[3] === 'test')) return [];
    37	    dependencies.push(match[3]);
    38	  }
    39	  return dependencies;
    40	}
