   198	      task: proposal.input.task,
   199	      context: proposal.input.context,
   200	    }, options);
   201	    return codingAgentToolResult(proposal.action, result);
   202	  }
   203	
   204	  if (proposal.action === 'RUN_TESTS') {
   205	    const expectedCommand = proposal.input.packageManager;
   206	    const expectedArgs = ['run', proposal.input.script];
   207	    if (
   208	      !isValidationScript(proposal.input.script) ||
   209	      !['pnpm', 'npm', 'yarn', 'bun'].includes(expectedCommand) ||
   210	      proposal.input.command !== expectedCommand ||
   211	      proposal.input.args.length !== expectedArgs.length ||
   212	      proposal.input.args.some((arg, index) => arg !== expectedArgs[index])
   213	    ) {
   214	      throw new ToolExecutionError('The validation proposal does not match its package-manager script.');
   215	    }
   216	  }
   217	  if (
   218	    proposal.action === 'RUN_COMMAND' &&
