   239	      command: proposal.input.command,
   240	      args: proposal.input.args,
   241	      cwd: proposal.input.root,
   242	      timeoutMs: DIAGNOSTIC_TIMEOUT_MS,
   243	    };
   244	  } else {
   245	    request = {
   246	      command: proposal.input.command,
   247	      args: proposal.input.args,
   248	      cwd: proposal.input.root,
   249	      timeoutMs: VALIDATION_TIMEOUT_MS,
