87:export async function inspectGitFiles(root: string): Promise<string[]> {
88:  const generated = ['node_modules', 'dist', 'traces', '.entire', '.cache', '.next', '.turbo', 'coverage', '.venv'];
89:  const output = await git(root, ['ls-files', '--cached', '--others',
90:    ...generated.map((name) => `--exclude=**/${name}/**`), '-z'], true);
91:  if (output !== '' && !output.endsWith('\0')) throw new Error('Git file metadata is incomplete.');
92:  return output === '' ? [] : [...new Set(output.slice(0, -1).split('\0'))].sort();
93:}
