101:async function readTopLevelFiles(root: string): Promise<string[]> {
102:  const directory = await opendir(root);
103:  const entries: string[] = [];
104:  let scanned = 0;
105:
106:  for await (const entry of directory) {
107:    scanned += 1;
108:    if (entry.name !== 'node_modules' && entry.name !== '.git') {
109:      entries.push(`${entry.name}${entry.isDirectory() ? '/' : ''}`);
110:    }
111:    if (scanned >= MAX_TOP_LEVEL_ENTRIES_SCANNED) break;
112:  }
113:
114:  return entries.sort().slice(0, MAX_TOP_LEVEL_FILES);
115:}
