117:async function readPackageMetadata(packageJsonPath: string): Promise<PackageMetadata> {
118:  if (!(await isRegularFile(packageJsonPath))) return { scripts: [] };
119:
120:  try {
121:    const packageJson = await open(packageJsonPath, 'r');
122:    try {
123:      const contents = Buffer.alloc(MAX_PACKAGE_JSON_BYTES + 1);
124:      const { bytesRead } = await packageJson.read(contents, 0, contents.length, 0);
125:      if (bytesRead > MAX_PACKAGE_JSON_BYTES) return { scripts: [] };
126:
127:      const parsed: unknown = JSON.parse(contents.subarray(0, bytesRead).toString('utf8'));
128:      if (!isRecord(parsed)) return { scripts: [] };
129:
130:      const packageName = typeof parsed.name === 'string'
131:        ? truncateText(parsed.name, MAX_PACKAGE_NAME_LENGTH)
132:        : undefined;
133:      const scripts = isRecord(parsed.scripts)
134:        ? Object.entries(parsed.scripts)
135:          .filter(([, value]) => typeof value === 'string')
136:          .map(([name]) => truncateText(name, MAX_SCRIPT_NAME_LENGTH))
137:          .sort()
138:          .slice(0, MAX_SCRIPTS)
139:        : [];
140:
141:      const validationCommands: Record<string, string> = {};
142:      for (const name of scripts.filter(isValidationScript)) {
143:        const command = isRecord(parsed.scripts) ? parsed.scripts[name] : undefined;
144:        if (typeof command === 'string') validationCommands[name] = command;
145:      }
146:      return { ...(packageName ? { packageName } : {}), scripts, validationCommands };
147:    } finally {
148:      await packageJson.close();
149:    }
150:  } catch {
151:    return { scripts: [] };
152:  }
153:}
