157:function withClarification(state: AgentState, information: string): AgentState {
158:  const evidence = currentEvidence(state);
159:  const normalized = information.replace(/\s+/gu, ' ').trim();
160:  const newInformation = normalized.length > 0 &&
161:    !evidence.clarifications.some((item) => item.text.replace(/\s+/gu, ' ').trim() === normalized);
162:  return {
163:    ...state,
164:    evidence: newInformation ? {
165:      ...evidence,
166:      revision: evidence.revision + 1,
167:      lastRevisionSource: 'user',
168:      clarifications: [...evidence.clarifications, { iteration: state.iteration, text: information }].slice(-8),
169:    } : evidence,
170:  };
171:}
