173:function withToolEvidence(
174:  state: AgentState,
175:  proposal: CandidateProposal,
176:  result: ToolResult,
177:  modified: string[],
178:  refreshFailed: boolean,
179:): AgentEvidence {
180:  const previous = currentEvidence(state);
181:  let evidence: AgentEvidence = { ...previous };
182:  if (!result.ok) {
183:    evidence.failures = [...previous.failures, {
184:      iteration: state.iteration,
185:      action: proposal.action,
186:      summary: truncateText(result.output, 1_000),
187:    }].slice(-8);
188:  }
189:  if (proposal.action === 'SEARCH_REPO' && result.ok) {
190:    const finding = { iteration: state.iteration, source: 'search' as const, paths: result.files.slice(0, 8) };
191:    if (!previous.findings.some((item) => item.source === finding.source &&
192:      JSON.stringify(item.paths) === JSON.stringify(finding.paths))) {
193:      evidence = {
194:        ...evidence,
195:        revision: evidence.revision + 1,
196:        lastRevisionSource: 'search',
197:        findings: [...previous.findings, finding].slice(-8),
198:      };
199:    }
200:  }
201:  if (proposal.action === 'READ_FILE' && result.ok) {
202:    const finding = {
203:      iteration: state.iteration,
204:      source: 'read' as const,
205:      paths: result.files.slice(0, 8),
206:      excerpt: truncateText(result.output, 1_000),
207:    };
208:    if (!previous.findings.some((item) => item.source === finding.source &&
209:      JSON.stringify(item.paths) === JSON.stringify(finding.paths) && item.excerpt === finding.excerpt)) {
210:      evidence = {
211:        ...evidence,
212:        revision: evidence.revision + 1,
213:        lastRevisionSource: 'read',
214:        findings: [...previous.findings, finding].slice(-8),
215:      };
216:    }
217:  }
218:  if (proposal.action === 'RUN_COMMAND' && result.ok) {
219:    const finding = {
220:      iteration: state.iteration,
221:      source: 'diagnostic' as const,
222:      paths: [],
223:      excerpt: truncateText(result.output, 1_000),
224:    };
225:    if (!previous.findings.some((item) => item.source === finding.source && item.excerpt === finding.excerpt)) {
226:      evidence = {
227:        ...evidence,
228:        revision: evidence.revision + 1,
229:        lastRevisionSource: 'diagnostic',
230:        findings: [...previous.findings, finding].slice(-8),
231:      };
232:    }
233:  }
234:  if (proposal.action === 'RUN_TESTS') {
235:    evidence.validation = {
236:      iteration: state.iteration,
237:      generation: previous.validationGeneration,
238:      script: proposal.input.script,
239:      exitCode: result.exitCode,
240:      timedOut: result.timedOut,
241:      passed: result.ok,
242:      summary: truncateText(result.output, 1_000),
243:    };
244:    evidence.validations = [...(previous.validations ?? []).filter((item) =>
245:      item.generation === previous.validationGeneration && item.script !== proposal.input.script), evidence.validation].slice(-8);
246:  }
247:  if (proposal.action === 'READ_ISSUE' && result.ok && result.issue) {
248:    evidence.issue = result.issue;
249:    evidence.revision += 1;
250:    evidence.lastRevisionSource = 'issue';
251:  }
252:  if (isCodingAgentProposal(proposal)) {
253:    const reportedEnvironmentLimitations: Array<'loopback_bind_denied'> =
254:      /\blisten\s+(?:EPERM|EACCES)\b/iu.test(result.output) ? ['loopback_bind_denied'] : [];
255:    evidence.validationGeneration = previous.validationGeneration + 1;
256:    evidence.worker = {
257:      iteration: state.iteration,
258:      agent: proposal.action === 'CALL_CODEX' ? 'codex' : 'claude',
259:      evidenceRevision: previous.revision,
260:      exitCode: result.exitCode,
261:      timedOut: result.timedOut,
262:      ok: result.ok,
263:      summary: truncateText(result.output, 500),
264:      modifiedFiles: refreshFailed ? [] : modified.slice(0, 8),
265:      ...(reportedEnvironmentLimitations.length ? { reportedEnvironmentLimitations } : {}),
266:    };
267:    evidence.repoRefreshRequired = refreshFailed;
268:  }
269:  return evidence;
270:}
