272:function completionAllowed(state: AgentState, policy: PolicyDecision): boolean {
273:  return hasPassedValidation(state) && (policy.selected === 'FINISH' ||
274:    (policy.selected === 'ASK_USER' && policy.completionReview !== undefined) ||
275:    (policy.selected === 'READ_FILE' && policy.completionReview === 'validated_inspection' && hasValidatedWorkerAttempt(state)));
276:}
277:
278:function allowedAlternatives(
279:  state: AgentState,
280:  policy: PolicyDecision,
281:): ExecutableAction[] {
282:  if (state.evidence?.repoRefreshRequired) return ['ASK_USER'];
283:  const preparation = taskPreparation(state);
284:  return EXECUTABLE_ACTIONS.filter((action) => {
285:    if (!isWorkerActionAllowed(action, state.workerSelection)) return false;
286:    if (preparation.nextAction !== null && requiresTaskPreparation(action)) return false;
287:    if (action === 'FINISH') {
288:      return completionAllowed(state, policy);
289:    }
290:    if (action === 'RUN_TESTS') return selectPendingValidation(state) !== undefined;
291:    if (action === 'READ_ISSUE') {
292:      const issue = parseGitHubIssue(state.task);
293:      return Boolean(issue && state.evidence?.issue?.url !== issue.url);
294:    }
295:    if (action === 'CALL_CODEX') return state.codexCalls < MAX_CODEX_CALLS;
296:    if (action === 'CALL_CLAUDE') return state.claudeCalls < MAX_CLAUDE_CALLS;
297:    return true;
298:  });
299:}
