321:type CodingAgentProposal = Extract<CandidateProposal, { action: 'CALL_CODEX' | 'CALL_CLAUDE' }>;
322:
323:function isCodingAgentProposal(proposal: CandidateProposal): proposal is CodingAgentProposal {
324:  return proposal.action === 'CALL_CODEX' || proposal.action === 'CALL_CLAUDE';
325:}
326:
327:function codingAgentName(proposal: CodingAgentProposal): 'Codex' | 'Claude' {
328:  return proposal.action === 'CALL_CODEX' ? 'Codex' : 'Claude';
329:}
330:
331:function codingAgentCommand(proposal: CodingAgentProposal): string {
332:  return proposal.action === 'CALL_CODEX' ? 'codex exec' : 'claude -p';
333:}
334:
335:function isToolResult(value: unknown, proposal: CandidateProposal): value is ToolResult {
336:  if (value === null || typeof value !== 'object') return false;
337:  const result = value as Partial<ToolResult>;
338:  const action = proposal.action;
339:  return result.action === action &&
340:    typeof result.ok === 'boolean' &&
341:    (result.exitCode === null || Number.isInteger(result.exitCode)) &&
342:    (!result.ok || (result.exitCode === 0 || (action === 'SEARCH_REPO' && result.exitCode === 1))) &&
343:    (!result.timedOut || !result.ok) &&
344:    (!result.cancelled || !result.ok) &&
345:    (result.cancelled === undefined || typeof result.cancelled === 'boolean') &&
346:    typeof result.durationMs === 'number' &&
347:    Number.isFinite(result.durationMs) &&
348:    result.durationMs >= 0 &&
349:    typeof result.timedOut === 'boolean' &&
350:    typeof result.output === 'string' &&
351:    Array.isArray(result.files) &&
352:    result.files.every((file) => typeof file === 'string') &&
353:    (result.stdout === undefined || typeof result.stdout === 'string') &&
354:    (result.stderr === undefined || typeof result.stderr === 'string') &&
355:    (proposal.action !== 'READ_ISSUE' || !result.ok ||
356:      (isIssueContext(result.issue) && result.issue.url === proposal.input.url));
357:}
358:
359:function modifiedFiles(repo: RepoSnapshot): string[] {
360:  return [...new Set(repo.gitStatus
361:    .map((entry) => entry.slice(3).trim())
362:    .filter(Boolean)
363:    .filter((entry) => entry !== 'traces' && entry !== 'traces/' && !entry.startsWith('traces/')))];
364:}
365:
366:async function safelyExecute(
367:  proposal: Exclude<CandidateProposal, { action: 'ASK_USER' | 'FINISH' }>,
368:  execute: typeof executeCandidate,
369:  options: ExecutionOptions,
370:): Promise<ToolResult> {
371:  const startedAt = performance.now();
372:  try {
373:    const result: unknown = await (options.signal ? execute(proposal, undefined, options) : execute(proposal));
374:    if (!isToolResult(result, proposal)) {
375:      throw new Error('The tool executor returned a malformed result.');
376:    }
377:    return options.signal?.aborted
378:      ? { ...result, ok: false, cancelled: true }
379:      : result;
380:  } catch (error) {
381:    return {
382:      action: proposal.action,
383:      ok: false,
384:      exitCode: null,
385:      durationMs: Math.round(performance.now() - startedAt),
386:      timedOut: false,
387:      ...(options.signal?.aborted ? { cancelled: true } : {}),
388:      output: truncateText(
389:        options.signal?.aborted ? 'Tool execution interrupted.' : error instanceof Error ? error.message : 'Tool execution failed.',
390:        MAX_OBSERVATION_LENGTH,
391:      ),
392:      files: [],
393:    };
394:  }
395:}
396:
397:function applyToolResult(
398:  state: AgentState,
399:  proposal: CandidateProposal,
400:  result: ToolResult,
401:  refreshedRepo?: RepoSnapshot,
402:  refreshFailed: boolean = false,
403:  workerCallReserved: boolean = false,
404:): AgentState {
405:  const signature = proposalSignature(proposal, state);
406:  const observations = [...state.observations];
407:  const failedApproaches = [...state.failedApproaches];
408:  let filesRead = state.filesRead;
409:  let filesModified = state.filesModified;
410:  let commandsRun = state.commandsRun;
411:  let tests = state.tests;
412:  let currentGoal = state.currentGoal;
413:  let repo = state.repo;
414:  let codexCalls = state.codexCalls;
415:  let claudeCalls = state.claudeCalls;
416:
417:  if (!result.ok) {
418:    failedApproaches.push(signature);
419:    observations.push(`${proposal.action} failed: ${truncateText(result.output, MAX_OBSERVATION_LENGTH)}`);
420:    currentGoal = 'Gather information before retrying a failed approach.';
421:  } else if (proposal.action === 'SEARCH_REPO') {
422:    const summary = result.files.length > 0 ? result.files.join(', ') : 'no matching files';
423:    observations.push(`Search completed: ${truncateText(summary, MAX_OBSERVATION_LENGTH)}`);
424:    currentGoal = 'Inspect a safe repository file informed by the search.';
425:  } else if (proposal.action === 'READ_FILE') {
426:    filesRead = [...new Set([...state.filesRead, ...result.files])];
427:    observations.push(`Read ${result.files[0] ?? proposal.input.path}: ${truncateText(result.output, MAX_OBSERVATION_LENGTH)}`);
428:    currentGoal = 'Validate the repository after inspection.';
429:  } else if (proposal.action === 'RUN_COMMAND') {
430:    const summary = truncateText(result.output, MAX_OBSERVATION_LENGTH);
431:    observations.push(`Diagnostic completed: ${summary}`);
432:    currentGoal = 'Use the approved diagnostic result to choose the next action.';
433:  } else if (proposal.action === 'RUN_TESTS') {
434:    const summary = truncateText(result.output, MAX_OBSERVATION_LENGTH);
435:    commandsRun = [...state.commandsRun, {
436:      command: commandDescription(proposal),
437:      exitCode: result.exitCode ?? 1,
438:      output: summary,
439:    }];
440:    tests = { ran: true, passed: true, summary };
441:    observations.push(`Validation passed: ${summary}`);
442:    currentGoal = 'Determine whether the requested task is complete.';
443:  } else if (proposal.action === 'READ_ISSUE') {
444:    observations.push(`Read linked GitHub issue (untrusted context): ${result.issue?.title ?? ''}`);
445:    currentGoal = 'Inspect repository instructions and implement the issue acceptance criteria.';
446:  } else if (isCodingAgentProposal(proposal)) {
447:    const summary = truncateText(result.output, MAX_OBSERVATION_LENGTH);
448:    commandsRun = [...state.commandsRun, {
449:      command: codingAgentCommand(proposal),
450:      exitCode: result.exitCode ?? 1,
451:      output: summary,
452:    }];
453:    observations.push(`${codingAgentName(proposal)} completed: ${summary}`);
454:    tests = { ran: false };
455:    currentGoal = `Validate the ${codingAgentName(proposal)} changes with an approved repository script.`;
456:  }
457:
458:  if (proposal.action === 'RUN_TESTS' && !result.ok) {
459:    const summary = truncateText(result.output, MAX_OBSERVATION_LENGTH);
460:    commandsRun = [...state.commandsRun, {
461:      command: commandDescription(proposal),
462:      exitCode: result.exitCode ?? 1,
463:      output: summary,
464:    }];
465:    tests = { ran: true, passed: false, summary };
466:  }
467:
468:  if (proposal.action === 'RUN_COMMAND') {
469:    const summary = truncateText(result.output, MAX_OBSERVATION_LENGTH);
470:    commandsRun = [...state.commandsRun, {
471:      command: commandDescription(proposal),
472:      exitCode: result.exitCode ?? 1,
473:      output: summary,
474:    }];
475:  }
476:
477:  if (isCodingAgentProposal(proposal)) {
478:    if (!workerCallReserved) {
479:      if (proposal.action === 'CALL_CODEX') codexCalls += 1;
480:      else claudeCalls += 1;
481:    }
482:    if (!result.ok) {
483:      const summary = truncateText(result.output, MAX_OBSERVATION_LENGTH);
484:      commandsRun = [...state.commandsRun, {
485:        command: codingAgentCommand(proposal),
486:        exitCode: result.exitCode ?? 1,
487:        output: summary,
488:      }];
489:    }
490:    if (refreshedRepo !== undefined) {
491:      repo = refreshedRepo;
492:      filesModified = modifiedFiles(refreshedRepo);
493:    }
494:    tests = { ran: false };
495:  }
496:
497:  const nextState: AgentState = {
498:    ...state,
499:    repo,
500:    currentGoal,
501:    filesRead,
502:    filesModified,
503:    observations,
504:    commandsRun,
505:    tests,
506:    failedApproaches,
507:    codexCalls,
508:    claudeCalls,
509:    evidence: withToolEvidence(state, proposal, result, filesModified, refreshFailed),
510:  };
511:  if (proposal.action === 'RUN_TESTS') {
512:    const pending = pendingValidationScripts(nextState);
513:    nextState.tests = {
514:      ran: true,
515:      ...(hasFailedValidation(nextState) ? { passed: false } : pending.length === 0 ? { passed: true } : {}),
516:      summary: truncateText(`Independent ${proposal.input.script}: ${result.ok ? 'passed' : 'failed'}. Pending: ${pending.join(', ') || 'none'}.\n${result.output}`, MAX_OBSERVATION_LENGTH),
517:    };
518:    nextState.currentGoal = pending.length ? `Validate remaining required checks: ${pending.join(', ')}.` : 'Determine whether the requested task is complete.';
519:  }
520:  return nextState;
521:}
