523:async function resolveApproval(
524:  initialProposal: CandidateProposal,
525:  state: AgentState,
526:  evaluation: EvaluationResult,
527:  policy: PolicyDecision,
528:  approve: OrchestrationDependencies['approve'],
529:  searchResults: string[],
530:  metrics: RunMetricsCollector,
531:  iterationLimit: number,
532:  signal?: AbortSignal,
533:  onProgress?: (proposals: CandidateProposal[], decisions: ApprovalDecision[]) => void,
534:): Promise<{
535:  proposals: CandidateProposal[];
536:  proposal: CandidateProposal;
537:  decision: ApprovalDecision;
538:  decisions: ApprovalDecision[];
539:}> {
540:  const proposals = [initialProposal];
541:  const decisions: ApprovalDecision[] = [];
542:  let proposal = initialProposal;
543:
544:  for (let attempt = 0; attempt <= MAX_APPROVAL_ALTERNATIVES; attempt += 1) {
545:    onProgress?.(proposals, decisions);
546:    const alternatives = allowedAlternatives(state, policy);
547:    const decision = await metrics.measure('approvalWaitMs', () => interruptible(() => {
548:      metrics.counts.approvalRequests += 1;
549:      const previous = decisions.at(-1);
550:      return approve({
551:        state,
552:        evaluation,
553:        policy,
554:        proposal: structuredClone(proposal),
555:        allowedAlternatives: [...alternatives],
556:        review: {
557:          source: previous?.kind === 'alternative' ? 'alternative' : 'policy',
558:          requested: previous?.kind === 'alternative' ? previous.action : policy.selected,
559:          iterationLimit,
560:          counts: {
561:            approvals: metrics.counts.approvals,
562:            alternatives: metrics.counts.alternatives,
563:            evaluationRecoveries: metrics.counts.evaluationRecoveries,
564:          },
565:        },
566:      });
567:    }, signal));
568:    metrics.recordApproval(decision);
569:    decisions.push(decision);
570:    onProgress?.(proposals, decisions);
571:    if (decision.kind !== 'alternative') return { proposals, proposal, decision, decisions };
572:    if (!alternatives.includes(decision.action)) {
573:      const rejection: ApprovalDecision = {
574:        kind: 'reject',
575:        reason: `${decision.action} is not a permitted alternative.`,
576:      };
577:      decisions.push(rejection);
578:      return {
579:        proposals,
580:        proposal,
581:        decision: rejection,
582:        decisions,
583:      };
584:    }
585:    proposal = repeatedFailureProposal(
586:      await interruptible(() => selectCandidate(decision.action, state, searchResults), signal),
587:      state,
588:    );
589:    proposals.push(proposal);
590:  }
591:
592:  const rejection: ApprovalDecision = {
593:    kind: 'reject',
594:    reason: 'Too many alternative selections.',
595:  };
596:  decisions.push(rejection);
597:  return {
598:    proposals,
599:    proposal,
600:    decision: rejection,
601:    decisions,
602:  };
603:}
604:
605:function repeatedFailureProposal(proposal: CandidateProposal, state: AgentState): CandidateProposal {
606:  if (!state.failedApproaches.includes(proposalSignature(proposal, state))) return proposal;
607:  return {
608:    action: 'ASK_USER',
609:    tool: null,
610:    input: null,
611:    reason: 'The same resolved candidate already failed; policy requires new information.',
612:  };
613:}
614:
615:function workerTraceRequest(
616:  proposal: CodingAgentProposal,
617:  state: AgentState,
618:  decision: ApprovalDecision,
619:): unknown {
620:  return {
621:    id: proposalSignature(proposal, state),
622:    evidenceRevision: state.evidence?.revision ?? 0,
623:    validationGeneration: state.evidence?.validationGeneration ?? 0,
624:    clarificationIterations: proposal.input.context.clarifications.map((item) => item.iteration),
625:    findingPaths: proposal.input.context.findings.flatMap((item) => item.paths).slice(0, 8),
