1064:            outcome: toolResult.cancelled ? 'cancelled' : toolResult.ok ? 'succeeded' : 'failed',
1065:            ...(isCodingAgentProposal(proposal) && isWorkerUsage(toolResult.usage) ? { usage: toolResult.usage } : {}),
1066:          }, nextState);
1067:        }
1068:      }
1069:
1070:      if (options.signal?.aborted) {
1071:        state = nextState;
1072:        throwIfInterrupted(options.signal);
1073:      }
1074:      const reachedLimit = terminalStatus === undefined && iteration === maxIterations;
1075:      if (reachedLimit) {
1076:        nextState = {
1077:          ...nextState,
1078:          observations: [...nextState.observations, `Stopped at the ${maxIterations}-iteration limit.`],
1079:          currentGoal: 'Ask the user how to continue after the iteration limit.',
1080:        };
1081:      }
1082:
1083:      state = nextState;
1084:      if (proposal.action === 'ASK_USER' && decision.kind === 'approve') {
1085:        await record({ type: 'clarification_recorded', iteration }, nextState);
1086:      }
1087:
1088:      phase = 'trace';
1089:      const summary = metrics.summary(nextState);
1090:      lastSummary = summary;
1091:      await appendOrchestrationTrace(trace, {
1092:        iteration,
1093:        stateBefore,
1094:        evaluation,
1095:        policy,
1096:        proposal: { considered: approval.proposals, selected: structuredClone(proposal) },
1097:        approval: { ...decision, history: approval.decisions },
1098:        toolInput: decision.kind === 'stop' ? null : proposal.input,
1099:        toolResult,
1100:        stateAfter: nextState,
1101:        metrics: { timings: summary.timings, counts: summary.counts, workerUsage: summary.workerUsage },
1102:        ...(terminalStatus !== undefined || reachedLimit ? { summary } : {}),
1103:        ...(isCodingAgentProposal(proposal) ? {
1104:          workerRequest: workerTraceRequest(proposal, stateBefore, decision),
1105:        } : {}),
1106:      });
