1108:        await record({ type: 'run_finished' }, nextState);
1109:      } else if (terminalStatus === 'stopped') {
1110:        await record({ type: 'run_stopped', reason: 'user', resumable: iteration < maxIterations }, nextState);
1111:      } else if (reachedLimit) {
1112:        await record({ type: 'iteration_limit' }, nextState);
1113:      }
1114:      state = nextState;
1115:      if (!options.persistence || (terminalStatus === undefined && !reachedLimit)) throwIfInterrupted(options.signal);
1116:
1117:      if (terminalStatus !== undefined) {
1118:        return {
1119:          status: terminalStatus,
1120:          state,
1121:          tracePath: trace.path,
1122:          iterations: iteration,
1123:          summary,
1124:        };
1125:      }
1126:    }
1127:
1128:    throwIfInterrupted(options.signal);
1129:    return {
1130:      status: 'iteration_limit',
1131:      state,
1132:      tracePath: trace.path,
1133:      iterations: maxIterations,
1134:      exitCode: 1,
1135:      summary: lastSummary,
1136:    };
1137:  } catch (error) {
1138:    if (error instanceof OrchestrationPersistenceFailure) return await persistenceFailureResult(error);
1139:    if (error instanceof RunInterruptedError || options.signal?.aborted) {
1140:      try {
1141:        return await stop();
1142:      } catch (stopError) {
1143:        if (stopError instanceof OrchestrationPersistenceFailure) return await persistenceFailureResult(stopError);
1144:        throw stopError;
1145:      }
1146:    }
1147:    if (error instanceof PromptStoppedError) {
1148:      try {
1149:        return await stop(error.reason);
1150:      } catch (stopError) {
1151:        if (stopError instanceof OrchestrationPersistenceFailure) return await persistenceFailureResult(stopError);
1152:        throw stopError;
1153:      }
1154:    }
1155:    throw error;
1156:  } finally {
1157:    options.signal?.removeEventListener('abort', latchPhase);
1158:  }
1159:}

1:import { lstat, open, opendir, realpath, stat } from 'node:fs/promises';
