8:export const MAX_PACKAGE_JSON_BYTES = 64 * 1024;
9:export const MAX_TOP_LEVEL_FILES = 80;
10:export const MAX_TOP_LEVEL_ENTRIES_SCANNED = 256;
11:export const MAX_SCRIPTS = 100;
12:export const MAX_GIT_OUTPUT_BYTES = 32 * 1024;
13:export const MAX_GIT_STATUS_ENTRIES = 100;
14:export const GIT_TIMEOUT_MS = 2_000;
