95:export async function orchestrationWorktreeRoot(root: string): Promise<string> {
96:  const canonical = await realpath(root);
97:  const gitRoot = await git(canonical, ['rev-parse', '--show-toplevel']);
98:  return gitRoot ? await realpath(gitRoot) : canonical;
99:}
