155:async function detectPackageManager(root: string): Promise<RepoSnapshot['packageManager']> {
156:  if (await isRegularFile(path.join(root, 'pnpm-lock.yaml'))) return 'pnpm';
157:  if (await isRegularFile(path.join(root, 'package-lock.json'))) return 'npm';
158:  if (await isRegularFile(path.join(root, 'yarn.lock'))) return 'yarn';
159:  if (
160:    (await isRegularFile(path.join(root, 'bun.lock'))) ||
161:    (await isRegularFile(path.join(root, 'bun.lockb')))
162:  ) {
163:    return 'bun';
164:  }
165:  return 'unknown';
166:}
