228:export async function inspectRepo(inputPath: string): Promise<RepoSnapshot> {
229:  const root = path.resolve(inputPath);
230:  let rootStat;
231:  try {
232:    rootStat = await stat(root);
233:  } catch {
234:    throw new Error(`Repository path does not exist: ${root}`);
235:  }
236:  if (!rootStat.isDirectory()) throw new Error(`Repository path must be a directory: ${root}`);
237:
238:  const packageJsonPath = path.join(root, 'package.json');
239:  const [topLevelFiles, packageMetadata, packageManager, gitMetadata] = await Promise.all([
240:    readTopLevelFiles(root),
241:    readPackageMetadata(packageJsonPath),
242:    detectPackageManager(root),
243:    inspectGit(root),
244:  ]);
245:
246:  const validationScripts = packageMetadata.scripts.filter(isValidationScript);
247:
248:  return {
249:    root,
250:    packageManager,
251:    ...(packageMetadata.packageName ? { packageName: packageMetadata.packageName } : {}),
252:    scripts: packageMetadata.scripts,
253:    validationScripts,
254:    ...validationWorkflow(validationScripts, packageMetadata.validationCommands ?? {}, packageManager),
255:    ...gitMetadata,
256:    topLevelFiles,
257:  };
258:}

1:import type { Action, AgentState } from '../types.js';
2:import { isIssueContext, parseGitHubIssue } from './issue.js';
3:
4:export const REPOSITORY_INSTRUCTION_FILES = ['AGENTS.md', 'CONTRIBUTING.md', 'CLAUDE.md'] as const;
5:
6:export type TaskPreparation = {
7:  issue: 'not_linked' | 'pending' | 'read' | 'provided';
8:  unreadInstructions: string[];
9:  nextAction: 'READ_ISSUE' | 'READ_FILE' | 'ASK_USER' | null;
10:};
11:
12:export function taskPreparation(state: AgentState): TaskPreparation {
13:  const issue = parseGitHubIssue(state.task);
14:  const resumedInstructions = state.evidence?.requiredInstructionFiles ?? [];
15:  const unreadInstructions = REPOSITORY_INSTRUCTION_FILES.filter((file) =>
16:    (resumedInstructions.includes(file) || (issue !== undefined && state.repo.topLevelFiles.includes(file))) && !state.filesRead.includes(file));
17:  if (!issue) return { issue: 'not_linked', unreadInstructions, nextAction: unreadInstructions.length ? 'READ_FILE' : null };
18:
19:  const issueRead = isIssueContext(state.evidence?.issue) && state.evidence.issue.url === issue.url;
20:  const failedReadIteration = state.evidence?.failures.find((failure) => failure.action === 'READ_ISSUE')?.iteration;
21:  const contextProvided = failedReadIteration !== undefined && Boolean(state.evidence?.clarifications.some((item) =>
22:    item.iteration > failedReadIteration && item.text.trim().length > 0));
23:  let nextAction: TaskPreparation['nextAction'] = null;
24:  if (!issueRead && !contextProvided) nextAction = failedReadIteration === undefined ? 'READ_ISSUE' : 'ASK_USER';
25:  else if (unreadInstructions.length > 0) nextAction = 'READ_FILE';
26:  return {
27:    issue: issueRead ? 'read' : contextProvided ? 'provided' : 'pending',
28:    unreadInstructions,
29:    nextAction,
30:  };
31:}
32:
33:export function requiresTaskPreparation(action: Action): boolean {
34:  return action === 'RUN_TESTS' || action === 'CALL_CODEX' || action === 'CALL_CLAUDE' || action === 'FINISH';
35:}

1:export const DIAGNOSTIC_COMMANDS = {
2:  git_status: {
3:    command: 'git',
4:    args: [
5:      '--no-pager',
6:      '--no-optional-locks',
7:      '-c',
8:      'core.fsmonitor=false',
9:      'status',
10:      '--short',
11:      '--untracked-files=all',
12:      '--no-renames',
13:      '--ignore-submodules=all',
14:      '--',
15:      '.',
16:      ':(exclude)traces/**',
17:    ],
18:  },
19:  git_diff_stat: {
20:    command: 'git',
21:    args: [
22:      '--no-pager',
23:      '--no-optional-locks',
24:      '-c',
25:      'core.fsmonitor=false',
26:      'diff',
27:      '--stat',
28:      '--no-ext-diff',
29:      '--no-textconv',
30:      '--no-renames',
31:      '--ignore-submodules=all',
32:      'HEAD',
33:      '--',
34:      '.',
35:      ':(exclude)traces/**',
36:    ],
37:  },
38:} as const;
39:
40:export type DiagnosticCommandId = keyof typeof DIAGNOSTIC_COMMANDS;
41:
42:export type DiagnosticCommand = {
43:  id: DiagnosticCommandId;
44:  command: string;
45:  args: string[];
46:};
47:
48:export function selectDiagnosticCommand(gitStatus: string[]): DiagnosticCommand {
49:  const id: DiagnosticCommandId = gitStatus.some((entry) => !entry.startsWith('??'))
50:    ? 'git_diff_stat'
51:    : 'git_status';
52:  const diagnostic = DIAGNOSTIC_COMMANDS[id];
53:  return {
54:    id,
55:    command: diagnostic.command,
56:    args: [...diagnostic.args],
57:  };
58:}
59:
60:export function isAllowedDiagnosticCommand(
61:  id: string,
62:  command: string,
63:  args: string[],
64:): boolean {
65:  if (!Object.hasOwn(DIAGNOSTIC_COMMANDS, id)) return false;
66:  const diagnostic = DIAGNOSTIC_COMMANDS[id as DiagnosticCommandId];
67:  return command === diagnostic.command &&
68:    args.length === diagnostic.args.length &&
69:    args.every((argument, index) => argument === diagnostic.args[index]);
70:}

