262	export async function selectCandidate(
263	  action: Action,
264	  state: AgentState,
265	  searchResults: string[] = [],
266	): Promise<CandidateProposal> {
267	  if (!isWorkerActionAllowed(action, state.workerSelection)) {
268	    return { action: 'ASK_USER', tool: null, input: null, reason: 'The worker selection for this run excludes the requested coding agent.' };
269	  }
270	  const preparation = taskPreparation(state);
271	  if (preparation.nextAction !== null && requiresTaskPreparation(action)) {
272	    return {
273	      action: 'ASK_USER', tool: null, input: null,
274	      reason: 'Required task context and repository instructions must be read before testing, delegation, or completion.',
275	    };
276	  }
277	  switch (action) {
278	    case 'SEARCH_REPO':
279	      return {
280	        action,
281	        tool: 'rg',
282	        input: { root: state.repo.root, terms: deriveSearchTerms(state.evidence?.issue?.title ?? state.task) },
283	      };
284	    case 'READ_ISSUE': {
285	      const issue = parseGitHubIssue(state.task);
286	      return issue && state.evidence?.issue?.url !== issue.url ? {
287	        action,
288	        tool: 'github_issue',
289	        input: { url: issue.url },
290	      } : {
291	        action: 'ASK_USER',
292	        tool: null,
293	        input: null,
294	        reason: issue ? 'The linked issue is already available as untrusted context.' : 'The task is not a supported GitHub issue URL.',
295	      };
296	    }
297	    case 'READ_FILE': {
298	      const requiredInstruction = preparation.unreadInstructions[0];
299	      if (requiredInstruction) {
300	        try {
301	          await resolveSafeRepoFile(state.repo.root, requiredInstruction);
302	          return { action, tool: 'read_file', input: { root: state.repo.root, path: requiredInstruction } };
303	        } catch (error) {
304	          if (!(error instanceof CandidateSelectionError)) throw error;
305	          return {
306	            action: 'ASK_USER', tool: null, input: null,
307	            reason: `The required repository instruction file ${requiredInstruction} cannot be read safely.`,
308	          };
309	        }
310	      }
311	      for (const candidate of preferredReadCandidates(state, searchResults)) {
312	        try {
313	          const safePath = await resolveSafeRepoFile(state.repo.root, candidate);
314	          return {
315	            action,
316	            tool: 'read_file',
317	            input: { root: state.repo.root, path: safePath },
318	          };
319	        } catch (error) {
320	          if (!(error instanceof CandidateSelectionError)) throw error;
321	        }
322	      }
323	      return {
324	        action: 'ASK_USER',
325	        tool: null,
326	        input: null,
327	        reason: 'No safe unread repository file is available.',
328	      };
329	    }
330	    case 'RUN_TESTS': {
331	      const script = selectPendingValidation(state);
332	      if (!script) {
333	        return {
334	          action: 'ASK_USER',
335	          tool: null,
336	          input: null,
337	          reason: hasPassedValidation(state)
338	            ? 'All required independent checks already passed; review the original task before completion.'
339	            : 'No declared validation script can cover the pending required checks.',
340	        };
341	      }
342	      if (state.repo.packageManager === 'unknown') {
343	        return {
344	          action: 'ASK_USER',
345	          tool: null,
346	          input: null,
347	          reason: 'The package manager could not be detected from a lockfile.',
348	        };
349	      }
350	      return {
351	        action,
352	        tool: 'package_script',
