  2	import { redactSensitiveText } from '../logging/trace.js';
  3	import { truncateText } from '../limits.js';
  4	import type { IssueContext } from '../types.js';
  5	import { isValidationScript, validationRequirementsFromText } from './validation.js';
  6	
  7	export const ISSUE_TIMEOUT_MS = 10_000;
  8	export const MAX_ISSUE_RESPONSE_BYTES = 64 * 1024;
  9	export const MAX_ISSUE_BODY_LENGTH = 4_000;
 10	
 11	export type GitHubIssue = { url: string; owner: string; repo: string; number: number };
 12	
 13	class IssueReadError extends Error {}
 14	
 15	export function parseGitHubIssue(task: string): GitHubIssue | undefined {
 16	  const match = /^https:\/\/github\.com\/([a-zA-Z0-9][a-zA-Z0-9-]{0,38})\/([a-zA-Z0-9_.-]{1,100})\/issues\/([1-9][0-9]{0,9})(?:[?#][^\s]*)?$/u.exec(task.trim());
 17	  if (!match?.[1] || !match[2] || !match[3] || ['.', '..'].includes(match[2])) return undefined;
 18	  const number = Number(match[3]);
 19	  return { owner: match[1], repo: match[2], number, url: `https://github.com/${match[1]}/${match[2]}/issues/${number}` };
 20	}
