 26	export function isIssueContext(value: unknown): value is IssueContext {
 27	  return isRecord(value) && Object.keys(value).every((key) => ['url', 'title', 'body', 'requestedValidationScripts', 'validationRequirementsTruncated', 'truncated'].includes(key)) &&
 28	    typeof value.url === 'string' && parseGitHubIssue(value.url)?.url === value.url &&
 29	    typeof value.title === 'string' && value.title.length <= 300 &&
 30	    typeof value.body === 'string' && value.body.length <= MAX_ISSUE_BODY_LENGTH &&
 31	    typeof value.truncated === 'boolean' && Array.isArray(value.requestedValidationScripts) &&
 32	    (value.validationRequirementsTruncated === undefined || typeof value.validationRequirementsTruncated === 'boolean') &&
 33	    value.requestedValidationScripts.length <= 8 && value.requestedValidationScripts.every((script) =>
 34	      typeof script === 'string' && isValidationScript(script));
 35	}
