 37	export async function readGitHubIssue(url: string, options: ExecutionOptions = {}): Promise<IssueContext> {
 38	  throwIfInterrupted(options.signal);
 39	  const issue = parseGitHubIssue(url);
 40	  if (!issue || issue.url !== url) throw new IssueReadError('Only a canonical GitHub issue URL can be read.');
 41	  const deadline = new AbortController();
 42	  const timer = setTimeout(() => deadline.abort(), ISSUE_TIMEOUT_MS);
 43	  const signal = options.signal ? AbortSignal.any([options.signal, deadline.signal]) : deadline.signal;
 44	  try {
 45	    const response = await interruptible(() => fetch(
 46	      `https://api.github.com/repos/${issue.owner}/${issue.repo}/issues/${issue.number}`, {
 47	        method: 'GET',
 48	        headers: { Accept: 'application/vnd.github+json' },
 49	        redirect: 'error',
 50	        signal,
 51	      },
 52	    ).then((response) => {
 53	      if (signal.aborted) {
 54	        void response.body?.cancel().catch(() => undefined);
 55	        throwIfInterrupted(signal);
 56	      }
 57	      return response;
 58	    }), signal);
 59	    if (!response.ok) {
 60	      void response.body?.cancel().catch(() => undefined);
 61	      throw new IssueReadError('Unable to read this public GitHub issue. Provide its context through ASK_USER.');
 62	    }
 63	    if (!response.body) throw new IssueReadError('GitHub returned an empty issue response.');
 64	    const reader = response.body.getReader();
 65	    const abort = (): void => { void reader.cancel().catch(() => undefined); };
 66	    signal.addEventListener('abort', abort, { once: true });
 67	    if (signal.aborted) abort();
 68	    const chunks: Uint8Array[] = [];
 69	    let bytes = 0;
 70	    try {
 71	      while (true) {
 72	        const { value, done } = await interruptible(() => reader.read(), signal);
 73	        throwIfInterrupted(signal);
 74	        if (done) break;
 75	        bytes += value.byteLength;
 76	        if (bytes > MAX_ISSUE_RESPONSE_BYTES) {
 77	          void reader.cancel().catch(() => undefined);
 78	          throw new IssueReadError('GitHub issue response exceeds the bounded read limit.');
 79	        }
 80	        chunks.push(value);
 81	      }
 82	    } finally {
 83	      signal.removeEventListener('abort', abort);
 84	      reader.releaseLock();
 85	    }
 86	    let data: unknown;
 87	    try { data = JSON.parse(Buffer.concat(chunks).toString('utf8')); } catch {
 88	      throw new IssueReadError('GitHub returned invalid issue data.');
 89	    }
 90	    const returnedIssue = isRecord(data) && typeof data.html_url === 'string' ? parseGitHubIssue(data.html_url) : undefined;
 91	    if (!isRecord(data) || returnedIssue?.owner.toLowerCase() !== issue.owner.toLowerCase() ||
 92	      returnedIssue.repo.toLowerCase() !== issue.repo.toLowerCase() || returnedIssue.number !== issue.number ||
 93	      data.number !== issue.number || data.pull_request !== undefined ||
 94	      typeof data.title !== 'string' || (data.body !== null && typeof data.body !== 'string')) {
 95	      throw new IssueReadError('GitHub returned invalid issue data.');
 96	    }
 97	    const title = redactSensitiveText(data.title);
 98	    const body = redactSensitiveText(data.body ?? '');
 99	    const requestedValidation = validationRequirementsFromText(`${title}\n${body}`);
100	    return {
101	      url,
102	      title: truncateText(title, 300),
103	      body: truncateText(body, MAX_ISSUE_BODY_LENGTH),
104	      requestedValidationScripts: requestedValidation.scripts,
105	      ...(requestedValidation.truncated ? { validationRequirementsTruncated: true } : {}),
106	      truncated: title.length > 300 || body.length > MAX_ISSUE_BODY_LENGTH,
107	    };
108	  } catch (error) {
109	    throwIfInterrupted(options.signal);
110	    if (deadline.signal.aborted) throw new IssueReadError('GitHub issue read timed out.');
111	    // Fetch failures can contain URLs or headers; retain only local safe errors.
112	    if (error instanceof IssueReadError) throw error;
113	    throw new IssueReadError('GitHub issue read failed. Provide its context through ASK_USER.');
114	  } finally {
115	    clearTimeout(timer);
116	  }
117	}

