  2	import { spawn } from 'node:child_process';
  3	
  4	export const MAX_PROCESS_OUTPUT_BYTES = 16 * 1024;
  5	export const FORCE_KILL_GRACE_MS = 1_000;
  6	
  7	export type ProcessRequest = {
  8	  command: string;
  9	  args: string[];
 10	  cwd: string;
 11	  timeoutMs: number;
 12	};
 13	
 14	export type ProcessResult = {
 15	  exitCode: number | null;
 16	  stdout: string;
 17	  stderr: string;
 18	  timedOut: boolean;
 19	  cancelled?: boolean;
 20	};
 21	
 22	export type ProcessOptions = ExecutionOptions & { onStdout?: (chunk: Buffer) => void };
 23	
 24	export type ProcessRunner = (request: ProcessRequest, options?: ProcessOptions) => Promise<ProcessResult>;
 25	
 26	export class ProcessExecutionError extends Error {
 27	  constructor(message: string) {
 28	    super(message);
 29	    this.name = 'ProcessExecutionError';
 30	  }
 31	}
 32	
 33	function appendBounded(current: Buffer[], chunk: Buffer, byteCount: { value: number }): void {
 34	  const available = MAX_PROCESS_OUTPUT_BYTES - byteCount.value;
 35	  if (available <= 0) return;
 36	  const bounded = chunk.subarray(0, available);
 37	  current.push(bounded);
 38	  byteCount.value += bounded.length;
 39	}
 40	
 41	export const runProcess: ProcessRunner = async (request, options = {}) => new Promise((resolve, reject) => {
 42	  if (options.signal?.aborted) {
 43	    resolve({ exitCode: null, stdout: '', stderr: '', timedOut: false, cancelled: true });
 44	    return;
 45	  }
 46	  const useProcessGroup = process.platform !== 'win32';
 47	  const child = spawn(request.command, request.args, {
 48	    cwd: request.cwd,
 49	    env: process.env,
 50	    detached: useProcessGroup,
 51	    shell: false,
 52	    stdio: ['ignore', 'pipe', 'pipe'],
 53	  });
 54	  const stdout: Buffer[] = [];
 55	  const stderr: Buffer[] = [];
 56	  const stdoutBytes = { value: 0 };
 57	  const stderrBytes = { value: 0 };
 58	  let timedOut = false;
 59	  let settled = false;
 60	  let cancelled = false;
 61	  let closed = false;
 62	  let closedExitCode: number | null = null;
 63	  let forceKillTimeout: NodeJS.Timeout | undefined;
 64	  const kill = (signal: NodeJS.Signals): void => {
 65	    try {
 66	      if (useProcessGroup && child.pid !== undefined) {
 67	        process.kill(-child.pid, signal);
 68	      } else {
 69	        child.kill(signal);
 70	      }
 71	    } catch {
 72	      child.kill(signal);
 73	    }
 74	  };
 75	  const finish = (): void => {
 76	    if (settled || !closed || forceKillTimeout !== undefined) return;
 77	    settled = true;
 78	    clearTimeout(timeout);
 79	    options.signal?.removeEventListener('abort', abort);
 80	    resolve({
 81	      exitCode: closedExitCode,
 82	      stdout: Buffer.concat(stdout).toString('utf8'),
 83	      stderr: Buffer.concat(stderr).toString('utf8'),
 84	      timedOut,
 85	      ...(cancelled ? { cancelled: true } : {}),
 86	    });
 87	  };
 88	  const terminate = (): void => {
 89	    if (forceKillTimeout !== undefined || settled) return;
 90	    kill('SIGTERM');
 91	    // Keep escalation even if the parent closes: its process group may still
 92	    // contain descendants that closed their inherited output and ignored TERM.
 93	    forceKillTimeout = setTimeout(() => {
 94	      kill('SIGKILL');
 95	      forceKillTimeout = undefined;
 96	      finish();
 97	    }, FORCE_KILL_GRACE_MS);
 98	  };
 99	  const abort = (): void => {
100	    cancelled = true;
101	    clearTimeout(timeout);
102	    terminate();
103	  };
104	  const timeout = setTimeout(() => {
105	    timedOut = true;
106	    terminate();
107	  }, request.timeoutMs);
108	  timeout.unref();
109	  options.signal?.addEventListener('abort', abort, { once: true });
110	  if (options.signal?.aborted) abort();
111	
112	  child.stdout.on('data', (chunk: Buffer) => {
113	    appendBounded(stdout, chunk, stdoutBytes);
114	    // Reporting must neither interrupt execution nor bypass process cleanup.
115	    try { options.onStdout?.(chunk); } catch { /* Ignore an unavailable reporting observer. */ }
116	  });
117	  child.stderr.on('data', (chunk: Buffer) => appendBounded(stderr, chunk, stderrBytes));
118	  child.on('error', (error) => {
119	    if (settled) return;
120	    settled = true;
121	    clearTimeout(timeout);
122	    if (forceKillTimeout !== undefined) clearTimeout(forceKillTimeout);
123	    options.signal?.removeEventListener('abort', abort);
124	    reject(new ProcessExecutionError(`Unable to start ${request.command}: ${error.message}`));
125	  });
126	  child.on('close', (exitCode) => {
127	    closed = true;
128	    closedExitCode = exitCode;
129	    finish();
130	  });
131	});
132	
133	export function validateProcessResult(result: ProcessResult): void {
134	  if (
135	    (result.exitCode !== null && !Number.isInteger(result.exitCode)) ||
136	    typeof result.stdout !== 'string' ||
137	    typeof result.stderr !== 'string' ||
138	    typeof result.timedOut !== 'boolean' ||
139	    (result.cancelled !== undefined && typeof result.cancelled !== 'boolean')
140	  ) {
141	    throw new ProcessExecutionError('The process runner returned a malformed result.');
142	  }
143	}

