 1	import { resolveEvaluationConfiguration, type EvaluationConfiguration } from '../config.js';
 2	import { requiredValidationScripts, validationRequirementsFromText } from '../repo/validation.js';
 3	import { REPOSITORY_INSTRUCTION_FILES } from '../repo/preparation.js';
