 9	export function resumePosition(checkpoint: SavedRunCheckpointV1, events: SavedRunEvent[]) {
10	  const stop = events.at(-1);
11	  if (checkpoint.status !== 'stopped' || stop?.type !== 'run_stopped' || !stop.resumable) {
12	    throw new Error('Resume requires a durable clean stop; active, blocked, finished, and exhausted runs are inspection only.');
13	  }
14	  const used = events.filter((event) => event.type === 'iteration_reserved').length;
15	  if (used >= checkpoint.iterationLimit) throw new Error('The original iteration budget is exhausted.');
16	  if (!stop.repositorySnapshotHash) throw new Error('This stop predates content fingerprints and remains inspection only. Start a new saved run.');
17	  const failure = [...events].reverse().find((event) => event.type === 'evaluation_failed');
18	  const recoveryRequired = failure !== undefined && !events.some((event) =>
19	    event.type === 'evaluation_completed' && event.sequence > failure.sequence);
20	  return {
21	    nextIteration: used + 1,
22	    segment: 2 + events.filter((event) => event.type === 'run_resumed').length,
23	    repositorySnapshotHash: stop.repositorySnapshotHash,
24	    recoveryRequired,
25	  };
26	}
