28	/** Reload secrets; defaults come from the frozen selection, never today's provider default. */
29	export function resolveResumeConfiguration(saved: SavedRunConfiguration, environment: NodeJS.ProcessEnv = process.env): EvaluationConfiguration | undefined {
30	  if (saved.mode === 'mock') return undefined;
31	  if (environment.ROUTER_MODEL !== undefined && environment.ROUTER_MODEL.trim() !== saved.model) {
32	    throw new Error('ROUTER_MODEL conflicts with the saved model selection.');
33	  }
34	  const configuration = resolveEvaluationConfiguration({
35	    ...environment,
36	    ...(environment.ROUTER_PROVIDER === undefined && environment.JEV_PROVIDER === undefined ? { ROUTER_PROVIDER: saved.provider } : {}),
37	    ...(environment.ROUTER_MODEL === undefined && !(saved.provider === 'openrouter' && environment.OPENROUTE_MODEL !== undefined)
38	      ? { ROUTER_MODEL: saved.model } : {}),
39	  });
40	  const current = createSavedRunConfiguration('live', configuration, saved.workerSelection, saved.codexNetworkAccess);
41	  if (JSON.stringify(current) !== JSON.stringify(saved)) {
42	    throw new Error('Provider, model, or Cloudflare account identity conflicts with this saved run.');
43	  }
44	  return configuration;
45	}
