47	export function refreshResumeState(checkpoint: SavedRunCheckpointV1, repo: RepoSnapshot, snapshot?: RepositorySnapshot): AgentState {
48	  const previous = checkpoint.state;
49	  const required = [...new Set([
50	    ...requiredValidationScripts(previous), ...validationRequirementsFromText(previous.task).scripts,
51	    ...(repo.requiredValidationScripts ?? repo.validationScripts),
52	  ])];
53	  if (required.length > 100 || validationRequirementsFromText(previous.task).truncated) {
54	    throw new Error('Original validation requirements cannot fit safely in the resumed state.');
55	  }
56	  const evidence = previous.evidence;
57	  const worker = evidence?.worker;
58	  const instructionFiles = REPOSITORY_INSTRUCTION_FILES.filter((file) => snapshot
59	    ? snapshot.files.some((item) => item.path === file && item.hash !== null) : repo.topLevelFiles.includes(file));
60	  const next: AgentState = {
61	    ...previous,
62	    repo: { ...repo, requiredValidationScripts: required,
63	      topLevelFiles: [...new Set([...instructionFiles, ...repo.topLevelFiles])].slice(0, 80) },
64	    currentGoal: 'Reinspect instructions and independently validate the preserved task before acceptance.',
65	    filesRead: [],
66	    filesModified: [],
67	    commandsRun: [],
68	    observations: ['Explicit continuation preserved the task and budgets. Earlier file reads and validation are stale. Repository drift may include operator edits.'],
69	    tests: { ran: false },
70	    evidence: {
71	      revision: (evidence?.revision ?? 0) + 1,
72	      validationGeneration: (evidence?.validationGeneration ?? 0) + 1,
73	      clarifications: evidence?.clarifications ?? [],
74	      failures: evidence?.failures ?? [],
75	      ...(evidence?.issue ? { issue: evidence.issue } : {}),
76	      findings: [],
77	      validations: [],
78	      requiredInstructionFiles: instructionFiles,
79	      // Prior process success is historical evidence, not fresh validation.
80	      ...(worker ? { worker: {
81	        ...worker, modifiedFiles: [],
82	        summary: 'An earlier segment attempted this worker. Fresh independent validation is required.',
83	      } } : {}),
84	    },
85	  };
86	  return redactAndValidateAgentState(next);
87	}
