89	export function validateSnapshotDrift(previous: RepositorySnapshot, current: RepositorySnapshot): string[] {
90	  for (const file of REPOSITORY_INSTRUCTION_FILES) {
91	    if (previous.files.some((item) => item.path === file && item.hash !== null) &&
92	        !current.files.some((item) => item.path === file && item.hash !== null)) {
93	      throw new Error('A previously present root instruction file is unavailable; restore it before continuation.');
94	    }
95	  }
96	  return changedSnapshotPaths(previous, current);
97	}
